mapper.select:
SELECT CAST(om.order_id AS CHAR) AS orderId, CAST(om.room_id AS CHAR) AS roomId, CAST(om.room_category_id AS CHAR) AS roomCategoryId, om.status AS orderStatus, om.start_at AS startAt, om.end_at AS endAt, om.created_at AS createdAt FROM order_main om WHERE om.camp_id = #{campId} AND om.is_deleted = 0 AND om.room_id IS NOT NULL AND om.status IN ('booked', 'checked_in', 'pending', 'refunding') AND om.start_at < #{rangeEndExclusive} AND om.end_at > #{rangeStart}
AND om.poi_id IN
#{poiId}
ORDER BY om.room_category_id ASC, om.room_id ASC, om.start_at ASC, om.order_id ASC
